// Remplacez "Validation" par le nom exact de votre nœud de validation
const input = $('Validation1').first().json;

const allErrors = Array.isArray(input.errors)
  ? input.errors
  : [];

const warnings = Array.isArray(input.warnings)
  ? input.warnings
  : [];

// On conserve seulement les vrais champs modifiables.
// Les champs controle_validation.* sont calculés automatiquement.
const errors = allErrors.filter(error => {
  const field = String(error.field || '');

  return (
    field &&
    !field.startsWith('controle_validation.')
  );
});

const originalData = input.data;

if (
  !originalData ||
  typeof originalData !== 'object' ||
  Array.isArray(originalData)
) {
  throw new Error(
    'Le nœud Validation ne contient pas un objet data valide.'
  );
}

function getNestedValue(object, path) {
  return String(path)
    .split('.')
    .reduce(
      (current, key) => current?.[key],
      object
    );
}

const errorFields = errors
  .map(error => error.field)
  .filter(Boolean);

const currentErrorValues = {};

for (const field of errorFields) {
  currentErrorValues[field] = getNestedValue(
    originalData,
    field
  );
}

return {
  json: {
    review_status: 'PENDING_REVIEW',

    invoice_number:
      originalData.facture?.numero ||
      originalData.document?.numero ||
      '',

    currency:
      originalData.document?.devise || '',

    validation_stage:
      input.stage || 'json_extraction',

    validation_errors: errors,

    validation_warnings: warnings,

    error_fields: errorFields,

    current_error_values: currentErrorValues,

    review_reason: errors
      .map(error =>
        `${error.field}: ${error.message}`
      )
      .join(' | '),

    original_data: JSON.parse(
      JSON.stringify(originalData)
    ),

    review_created_at:
      new Date().toISOString(),
  },
};

// ============================================================
// PRÉPARER UN FORMULAIRE UNIVERSEL DE CORRECTION
// Mode : Run Once for Each Item
// ============================================================

function deepClone(value) {
  if (value === undefined) {
    return undefined;
  }

  return JSON.parse(JSON.stringify(value));
}

function getByPath(target, path) {
  if (!target || !path) {
    return undefined;
  }

  const parts = String(path)
    .replace(/\[(\d+)\]/g, '.$1')
    .split('.')
    .filter(Boolean);

  let current = target;

  for (const part of parts) {
    if (
      current === null ||
      current === undefined
    ) {
      return undefined;
    }

    current = current[part];
  }

  return current;
}

function inferType(field, value) {
  if (typeof value === 'number') {
    return 'number';
  }

  if (typeof value === 'boolean') {
    return 'boolean';
  }

  const normalizedField =
    String(field || '').toLowerCase();

  if (normalizedField.includes('date')) {
    return 'date';
  }

  if (
    normalizedField.includes('quantite') ||
    normalizedField.includes('prix') ||
    normalizedField.includes('remise') ||
    normalizedField.includes('tva') ||
    normalizedField.includes('montant') ||
    normalizedField.includes('total') ||
    normalizedField.includes('frais') ||
    normalizedField.includes('tax') ||
    normalizedField.includes('timbre')
  ) {
    return 'number';
  }

  return 'text';
}

function humanLabel(field) {
  const labels = {
    'document.type_document':
      'Type de document',

    'document.code_type_document':
      'Code du type de document',

    'document.numero':
      'Numéro de facture',

    'document.date':
      'Date de facture',

    'document.date_echeance':
      'Date d’échéance',

    'document.devise':
      'Devise',

    'fournisseur.nom':
      'Nom du fournisseur',

    'fournisseur.identifiant':
      'Identifiant du fournisseur',

    'fournisseur.type_identifiant':
      'Type d’identifiant du fournisseur',

    'fournisseur.pays':
      'Pays du fournisseur',

    'client.nom':
      'Nom du client',

    'client.identifiant':
      'Identifiant du client',

    'client.code_client':
      'Code client',

    'client.type_identifiant':
      'Type d’identifiant du client',

    'client.pays':
      'Pays du client',

    'totaux.total_ht':
      'Total HT',

    'totaux.base_tva':
      'Base TVA',

    'totaux.montant_tva':
      'Montant TVA',

    'totaux.total_ttc':
      'Total TTC',

    'totaux.net_a_payer':
      'Net à payer',

    'totaux.tax_rate':
      'Taux de TVA',

    'totaux.timbre_fiscal':
      'Timbre fiscal',

    'totaux.frais_port_non_soumis':
      'Frais de port non soumis',

    'totaux.frais_port_soumis':
      'Frais de port soumis',

    'totaux.taxes_cpl':
      'Taxes complémentaires',
  };

  if (labels[field]) {
    return labels[field];
  }

  const lineMatch = String(field).match(
    /^lignes\[(\d+)\]\.(.+)$/
  );

  if (lineMatch) {
    const lineNumber =
      Number(lineMatch[1]) + 1;

    const property =
      lineMatch[2];

    const lineLabels = {
      reference: 'Référence',
      designation: 'Désignation',
      quantite: 'Quantité',
      prix_unitaire: 'Prix unitaire',
      remise: 'Remise',
      taux_tva: 'Taux de TVA',
      montant_ht: 'Montant HT',
    };

    return (
      (lineLabels[property] || property) +
      ' de l’article ' +
      lineNumber
    );
  }

  return String(field);
}

const state = deepClone($json);

const workingData = deepClone(
  state.working_data ||
  state.original_data ||
  state.data ||
  {}
);

const errors = Array.isArray(
  state.validation_errors
)
  ? state.validation_errors
  : Array.isArray(state.errors)
    ? state.errors
    : [];

const warnings = Array.isArray(
  state.validation_warnings
)
  ? state.validation_warnings
  : Array.isArray(state.warnings)
    ? state.warnings
    : [];

const issues = [
  ...errors.map(issue => ({
    ...issue,
    severity: 'ERROR',
  })),

  ...warnings.map(issue => ({
    ...issue,
    severity: 'WARNING',
  })),
];

const correctionSchema = [];
const correctionValues = {};
const descriptionLines = [];

for (
  let index = 0;
  index < issues.length;
  index++
) {
  const issue = issues[index];

  if (!issue || !issue.field) {
    continue;
  }

  const field = String(issue.field);

  const currentValue =
    issue.actual !== undefined
      ? issue.actual
      : getByPath(
          workingData,
          field
        );

  let suggestedValue;

  if (
    issue.suggested_value !== undefined &&
    issue.suggested_value !== null
  ) {
    suggestedValue =
      issue.suggested_value;
  } else if (
    issue.expected !== undefined &&
    issue.expected !== null
  ) {
    suggestedValue =
      issue.expected;
  } else {
    suggestedValue =
      currentValue ?? '';
  }

  const label =
    issue.label ||
    humanLabel(field);

  const valueType =
    issue.value_type ||
    inferType(field, currentValue);

  correctionSchema.push({
    index,
    severity:
      issue.severity || 'WARNING',

    code:
      issue.code || 'VALIDATION_ISSUE',

    field,

    label,

    message:
      issue.message ||
      'Champ à vérifier',

    current_value:
      currentValue ?? '',

    suggested_value:
      suggestedValue ?? '',

    value_type:
      valueType,

    required:
      issue.required === true ||
      issue.severity === 'ERROR',
  });

  /*
   * Le JSON affiché dans le formulaire contient :
   *
   * {
   *   "totaux.base_tva": 338.24,
   *   "totaux.montant_tva": 67.65
   * }
   */
  correctionValues[field] =
    suggestedValue ?? '';

  descriptionLines.push(
    `${index + 1}. ${label}\n` +
    `Problème : ${issue.message || ''}\n` +
    `Valeur actuelle : ${JSON.stringify(currentValue ?? '')}\n` +
    `Valeur proposée : ${JSON.stringify(suggestedValue ?? '')}`
  );
}

const correctionsJson = JSON.stringify(
  correctionValues,
  null,
  2
);

return {
  json: {
    ...state,

    working_data:
      workingData,

    correction_schema:
      correctionSchema,

    correction_count:
      correctionSchema.length,

    corrections_json:
      correctionsJson,

    form_description:
      descriptionLines.length > 0
        ? descriptionLines.join(
            '\n\n'
          )
        : 'Aucune correction nécessaire.',

    has_corrections:
      correctionSchema.length > 0,

    universal_form_prepared_at:
      new Date().toISOString(),
  },
};

// ============================================================
// APPLIQUER LES CORRECTIONS UNIVERSELLES
// Mode : Run Once for Each Item
// ============================================================

function deepClone(value) {
  if (value === undefined) {
    return undefined;
  }

  return JSON.parse(JSON.stringify(value));
}

function setByPath(target, path, value) {
  const parts = String(path)
    .replace(/\[(\d+)\]/g, '.$1')
    .split('.')
    .filter(Boolean);

  if (parts.length === 0) {
    throw new Error(
      'Chemin de correction vide.'
    );
  }

  let current = target;

  for (
    let index = 0;
    index < parts.length - 1;
    index++
  ) {
    const part = parts[index];
    const nextPart = parts[index + 1];

    const nextIsArrayIndex =
      /^\d+$/.test(nextPart);

    if (
      current[part] === undefined ||
      current[part] === null
    ) {
      current[part] =
        nextIsArrayIndex
          ? []
          : {};
    }

    current = current[part];
  }

  const finalPart =
    parts[parts.length - 1];

  current[finalPart] = value;
}

function getByPath(target, path) {
  const parts = String(path)
    .replace(/\[(\d+)\]/g, '.$1')
    .split('.')
    .filter(Boolean);

  let current = target;

  for (const part of parts) {
    if (
      current === undefined ||
      current === null
    ) {
      return undefined;
    }

    current = current[part];
  }

  return current;
}

function convertValue(value, valueType) {
  if (
    value === undefined ||
    value === null
  ) {
    return value;
  }

  if (valueType === 'number') {
    const parsed = Number(
      String(value)
        .trim()
        .replace(/\s/g, '')
        .replace(',', '.')
    );

    if (!Number.isFinite(parsed)) {
      throw new Error(
        `"${value}" n'est pas un nombre valide.`
      );
    }

    return parsed;
  }

  if (valueType === 'boolean') {
    return [
      'true',
      '1',
      'oui',
      'yes',
      'vrai',
    ].includes(
      String(value)
        .trim()
        .toLowerCase()
    );
  }

  return String(value).trim();
}

const formResult =
  deepClone($json);

const previousState =
  deepClone(
    $('Préparer formulaire universel')
      .item
      .json
  );

const workingData =
  deepClone(
    previousState.working_data ||
    previousState.original_data ||
    previousState.data ||
    {}
  );

const correctionSchema =
  Array.isArray(
    previousState.correction_schema
  )
    ? previousState.correction_schema
    : [];

const rawCorrections =
  formResult.corrections_json;

if (
  rawCorrections === undefined ||
  rawCorrections === null ||
  String(rawCorrections).trim() === ''
) {
  throw new Error(
    'Le champ corrections_json est vide.'
  );
}

let submittedCorrections;

try {
  submittedCorrections =
    typeof rawCorrections === 'object'
      ? rawCorrections
      : JSON.parse(
          String(rawCorrections)
        );
} catch (error) {
  throw new Error(
    'Le JSON des corrections est invalide. ' +
    'Vérifiez les guillemets, les virgules et les accolades.'
  );
}

if (
  !submittedCorrections ||
  Array.isArray(submittedCorrections) ||
  typeof submittedCorrections !== 'object'
) {
  throw new Error(
    'corrections_json doit contenir un objet JSON.'
  );
}

const schemaByField = {};

for (const definition of correctionSchema) {
  if (
    definition &&
    definition.field
  ) {
    schemaByField[
      definition.field
    ] = definition;
  }
}

const correctionHistory =
  Array.isArray(
    previousState.correction_history
  )
    ? deepClone(
        previousState.correction_history
      )
    : [];

const appliedCorrections = [];

for (
  const [field, submittedValue]
  of Object.entries(
    submittedCorrections
  )
) {
  const definition =
    schemaByField[field];

  if (!definition) {
    throw new Error(
      `Le champ "${field}" ne fait pas partie des corrections autorisées.`
    );
  }

  if (
    definition.required === true &&
    (
      submittedValue === undefined ||
      submittedValue === null ||
      String(submittedValue).trim() === ''
    )
  ) {
    throw new Error(
      `Une valeur est obligatoire pour "${definition.label}".`
    );
  }

  const previousValue =
    getByPath(
      workingData,
      field
    );

  const convertedValue =
    convertValue(
      submittedValue,
      definition.value_type ||
      'text'
    );

  setByPath(
    workingData,
    field,
    convertedValue
  );

  const historyEntry = {
    code:
      definition.code,

    field,

    label:
      definition.label,

    severity:
      definition.severity,

    previous_value:
      previousValue,

    new_value:
      convertedValue,

    value_type:
      definition.value_type,

    corrected_at:
      new Date().toISOString(),
  };

  appliedCorrections.push(
    historyEntry
  );

  correctionHistory.push(
    historyEntry
  );
}

// Vérifier que toutes les erreurs obligatoires
// sont présentes dans le JSON envoyé.
const missingRequiredFields =
  correctionSchema.filter(
    definition =>
      definition.required === true &&
      !Object.prototype.hasOwnProperty.call(
        submittedCorrections,
        definition.field
      )
  );

if (missingRequiredFields.length > 0) {
  throw new Error(
    'Corrections obligatoires absentes : ' +
    missingRequiredFields
      .map(item => item.label)
      .join(', ')
  );
}

return {
  json: {
    ...previousState,

    invoice_number:
      workingData.document?.numero ||
      previousState.invoice_number ||
      '',

    working_data:
      deepClone(workingData),

    original_data:
      deepClone(workingData),

    correction_history:
      correctionHistory,

    applied_corrections:
      appliedCorrections,

    applied_correction_count:
      appliedCorrections.length,

    review_status:
      'CORRECTED_PENDING_REVALIDATION',

    human_review_completed:
      true,

    needs_revalidation:
      true,

    human_reviewed_at:
      new Date().toISOString(),
  },
};
